 77	            System.out.println("Using default values.");
 78	            depth = DEFAULT_DEPTH;
 79	            width = DEFAULT_WIDTH;
 80	        }
 81	        
 82	        organisms = new ArrayList<>();
 83	        field = new Field(depth, width);
 84	
 85	        // Create a view of the state of each location in the field.
 86	        view = new SimulatorView(depth, width, step);
 87	        for(PopulationRule rule : POPULATION_RULES) {
 88	            view.setColor(rule.getSpecies(), rule.getColor());
 89	        }
 90	        
 91	        // Setup a valid starting point.
 92	        reset();
 93	    }
