107	    // Functional methods
108	    
109	    /**
110	     * Run the simulation from its current state for a reasonably long period,
111	     * (4000 steps).
112	     */
113	    public void runLongSimulation()
114	    {
115	        simulate(4000);
116	    }
117	    
118	    /**
119	     * Run the simulation from its current state for the given number of steps.
120	     * Stop before the given number of steps if it ceases to be viable.
121	     * @param numSteps The number of steps to run for.
122	     */
123	    public void simulate(int numSteps)
124	    {
125	        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
126	            simulateOneStep();
127	            //delay(60);   // uncomment this to run more slowly
128	        }
129	    }
