131	    /**
132	     * Run the simulation from its current state for a single step.
133	     * Iterate over the whole field updating the state of each
134	     * fox and rabbit.
135	     */
136	    public void simulateOneStep()
137	    {
138	        step++;
139	        randomWeather();
140	        // Provide space for newborn animals.
141	        List<Organism> newOrganisms = new ArrayList<>();        
142	        // Let all rabbits act.
143	        for(Iterator<Organism> it = organisms.iterator(); it.hasNext(); ) {
144	            Organism organism = it.next();
145	            
146	            if (organism.isDiurnal() && step % 80 <= 55) {
147	                organism.act(newOrganisms);
148	            }
149	            else if (!organism.isDiurnal() && step % 80 > 55) {
150	                organism.act(newOrganisms);
151	            }
152	            if(! organism.isAlive()) {
153	                it.remove();
154	            }
155	        }
156	                   
157	        // Add the newly born organisms to the main lists.
158	        organisms.addAll(newOrganisms);
159	        view.showStatus(step, field);
160	    }
161	        
162	    /**
163	     * Reset the simulation to a starting position.
164	     */
165	    public void reset()
166	    {
167	        step = 0;
168	        organisms.clear();
169	        populate();
170	        weather.resetWeather();
171	        
172	        // Show the starting state in the view.
173	        view.showStatus(step, field);
174	    }
175	    
176	    /**
177	     * Randomly populate the field with foxes and rabbits.
178	     */
179	    private void populate()
180	    {
181	        Random rand = Randomizer.getRandom();
182	        field.clear();
183	        for(int row = 0; row < field.getDepth(); row++) {
184	            for(int col = 0; col < field.getWidth(); col++) {
185	                seedLocation(rand, new Location(row, col));
186	            }
187	        }
188	    }
189	    
190	    /**
191	     * Pause for a given time.
192	     * @param millisec  The time to pause for, in milliseconds
193	     */
194	    private void delay(int millisec)
195	    {
196	        try {
197	            Thread.sleep(millisec);
198	        }
199	        catch (InterruptedException ie) {
200	            // wake up
201	        }
202	    }
203	    
204	    /**
205	     * Randomises the weather
206	     */
207	    public void randomWeather() {
208	        if (step % 450 == 0) {
209	            weather.changeWeather();
210	        }
211	    }
212	
213	    /**
214	     * Populate one location by selecting the first species whose creation
215	     * probability passes. Each cell can contain at most one organism.
216	     */
217	    private void seedLocation(Random rand, Location location)
218	    {
219	        for(PopulationRule rule : POPULATION_RULES) {
220	            if(rand.nextDouble() <= rule.getCreationProbability()) {
221	                organisms.add(rule.create(field, location));
222	                return;
223	            }
224	        }
225	    }
226	}

