142	    public void simulateOneStep()
143	    {
144	        step++;
145	        randomWeather();
146	        // Provide space for newborn animals.
147	        List<Organism> newOrganisms = new ArrayList<>();        
148	        // Let all rabbits act.
149	        for(Iterator<Organism> it = organisms.iterator(); it.hasNext(); ) {
150	            Organism organism = it.next();
151	            
152	            if (organism.isDiurnal() && step % 80 <= 55) {
153	                organism.act(newOrganisms);
154	            }
155	            else if (!organism.isDiurnal() && step % 80 > 55) {
156	                organism.act(newOrganisms);
