  1	import java.util.Collections;
  2	import java.util.Iterator;
  3	import java.util.LinkedList;
  4	import java.util.List;
  5	import java.util.Random;
  6	
  7	/**
  8	 * Represent a rectangular grid of field positions.
  9	 * Each position is able to store a single animal.
 10	 *
 11	 * @version 2016.02.29
 12	 */
 13	public class Field
 14	{
 15	    // A random number generator for providing random locations.
 16	    private static final Random rand = Randomizer.getRandom();
 17	    
 18	    // The depth and width of the field.
 19	    private int depth, width;
 20	    // Storage for the organisms.
 21	    private Organism[][] field;
 22	
 23	    /**
 24	     * Represent a field of the given dimensions.
 25	     * @param depth The depth of the field.
 26	     * @param width The width of the field.
 27	     */
 28	    public Field(int depth, int width)
 29	    {
 30	        this.depth = depth;
 31	        this.width = width;
 32	        field = new Organism[depth][width];
 33	    }
 34	    
 35	    /**
 36	     * Empty the field.
 37	     */
 38	    public void clear()
 39	    {
 40	        for(int row = 0; row < depth; row++) {
 41	            for(int col = 0; col < width; col++) {
 42	                field[row][col] = null;
 43	            }
 44	        }
 45	    }
 46	    
 47	    /**
 48	     * Clear the given location.
 49	     * @param location The location to clear.
 50	     */
 51	    public void clear(Location location)
 52	    {
 53	        field[location.getRow()][location.getCol()] = null;
 54	    }
 55	    
 56	    /**
 57	     * Place an animal at the given location.
 58	     * If there is already an animal at the location it will
 59	     * be lost.
 60	     * @param animal The animal to be placed.
 61	     * @param row Row coordinate of the location.
 62	     * @param col Column coordinate of the location.
 63	     */
 64	    public void place(Organism organism, int row, int col)
 65	    {
 66	        place(organism, new Location(row, col));
 67	    }
 68	    
 69	    /**
 70	     * Place an animal at the given location.
 71	     * If there is already an animal at the location it will
 72	     * be lost.
 73	     * @param animal The animal to be placed.
 74	     * @param location Where to place the animal.
 75	     */
 76	    public void place(Organism organism, Location location)
 77	    {
 78	        field[location.getRow()][location.getCol()] = organism;
 79	    }
 80	    
 81	    /**
 82	     * Return the animal at the given location, if any.
 83	     * @param location Where in the field.
 84	     * @return The animal at the given location, or null if there is none.
 85	     */
 86	    public Organism getObjectAt(Location location)
 87	    {
 88	        return getObjectAt(location.getRow(), location.getCol());
 89	    }
 90	    
 91	    /**
 92	     * Return the animal at the given location, if any.
 93	     * @param row The desired row.
 94	     * @param col The desired column.
 95	     * @return The animal at the given location, or null if there is none.
 96	     */
 97	    public Organism getObjectAt(int row, int col)
 98	    {
 99	        return field[row][col];
100	    }
101	    
102	    /**
103	     * Generate a random location that is adjacent to the
104	     * given location, or is the same location.
105	     * The returned location will be within the valid bounds
106	     * of the field.
107	     * @param location The location from which to generate an adjacency.
108	     * @return A valid location within the grid area.
109	     */
110	    public Location randomAdjacentLocation(Location location)
111	    {
112	        List<Location> adjacent = adjacentLocations(location);
113	        return adjacent.get(0);
114	    }
115	    
116	    /**
117	     * Get a shuffled list of the free adjacent locations.
118	     * @param location Get locations adjacent to this.
119	     * @return A list of free adjacent locations.
120	     */
121	    public List<Location> getFreeAdjacentLocations(Location location)
122	    {
123	        List<Location> free = new LinkedList<>();
124	        List<Location> adjacent = adjacentLocations(location);
125	        for(Location next : adjacent) {
126	            if(getObjectAt(next) == null) {
127	                free.add(next);
128	            }
129	        }
130	        return free;
131	    }
132	    
133	    /**
134	     * Try to find a free location that is adjacent to the
135	     * given location. If there is none, return null.
136	     * The returned location will be within the valid bounds
137	     * of the field.
138	     * @param location The location from which to generate an adjacency.
139	     * @return A valid location within the grid area.
140	     */
141	    public Location freeAdjacentLocation(Location location)
142	    {
143	        // The available free ones.
144	        List<Location> free = getFreeAdjacentLocations(location);
145	        if(free.size() > 0) {
146	            return free.get(0);
147	        }
148	        else {
149	            return null;
150	        }
151	    }
152	
153	    /**
154	     * Return a shuffled list of locations adjacent to the given one.
155	     * The list will not include the location itself.
156	     * All locations will lie within the grid.
157	     * @param location The location from which to generate adjacencies.
158	     * @return A list of locations adjacent to that given.
159	     */
160	    public List<Location> adjacentLocations(Location location)
161	    {
162	        assert location != null : "Null location passed to adjacentLocations";
163	        // The list of locations to be returned.
164	        List<Location> locations = new LinkedList<>();
165	        if(location != null) {
166	            int row = location.getRow();
167	            int col = location.getCol();
168	            for(int roffset = -1; roffset <= 1; roffset++) {
169	                int nextRow = row + roffset;
170	                if(nextRow >= 0 && nextRow < depth) {
171	                    for(int coffset = -1; coffset <= 1; coffset++) {
172	                        int nextCol = col + coffset;
173	                        // Exclude invalid locations and the original location.
174	                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
175	                            locations.add(new Location(nextRow, nextCol));
176	                        }
177	                    }
178	                }
179	            }
180	            
181	            // Shuffle the list. Several other methods rely on the list
182	            // being in a random order.
183	            Collections.shuffle(locations, rand);
184	        }
185	        return locations;
186	    }
187	
188	    /**
189	     * Return the depth of the field.
190	     * @return The depth of the field.
191	     */
192	    public int getDepth()
193	    {
194	        return depth;
195	    }
196	    
197	    /**
198	     * Return the width of the field.
199	     * @return The width of the field.
200	     */
201	    public int getWidth()
202	    {
203	        return width;
204	    }
205	}

