147	    public void showStatus(int step, Field field)
148	    {
149	        if(!isVisible()) {
150	            setVisible(true);
151	        }
152	            
153	        stepLabel.setText(STEP_PREFIX + step);
154	        stats.reset();
155	        
156	        fieldView.preparePaint();
157	
158	        for(int row = 0; row < field.getDepth(); row++) {
159	            for(int col = 0; col < field.getWidth(); col++) {
160	                Organism organism = field.getObjectAt(row, col);
161	                if(organism != null) {
162	                    stats.incrementCount(organism.getSpecies());
163	                    fieldView.drawMark(col, row, getColor(organism.getSpecies()));
164	                }
165	                else {
166	                    fieldView.drawMark(col, row, EMPTY_COLOR);
167	                }
168	            }
169	        }
170	        stats.countFinished();
171	
172	        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
173	        fieldView.repaint();
174	    }
